// Вход в Firebase (email+пароль) — база закрыта, нужен токен доступа
const FB_API_KEY = 'AIzaSyBo3gJb9XIuK_12ZSwTvQkk1XQ-tGI5nYY'; // Web API Key — не секрет
const BOT_EMAIL = 'ВСТАВЬ_ПОЧТУ_ДЛЯ_ВХОДА';
const BOT_PASSWORD = 'ВСТАВЬ_ПАРОЛЬ_ДЛЯ_ВХОДА';
const auth = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://identitytoolkit.googleapis.com/v1/accounts:signInWithPassword?key=' + FB_API_KEY,
  body: { email: BOT_EMAIL, password: BOT_PASSWORD, returnSecureToken: true },
  json: true
});
return [{ json: { idToken: auth.idToken } }];

// Превращаем объект /outbox в отдельные сообщения на отправку
const data = $json;
const idToken = $('Войти в Firebase').first().json.idToken;
if (!data || typeof data !== 'object' || Array.isArray(data)) return [];
const out = [];
for (const key of Object.keys(data)) {
  const it = data[key] || {};
  if (!it.chatId || !it.text) continue;
  out.push({ json: { key, chatId: it.chatId, text: it.text, idToken } });
}
return out;
